/*
 * Agent trust (agent_trust.h) against grants, manifests and keys the hub's
 * own Go encoders signed (trust_fixtures.h, regenerated by
 * hub/pkg/response/trust_fixtures_test.go). Builds with gcc (POSIX file
 * backend) and with mingw (Win32 backend); both must pass.
 *
 * The rule under test: an action outside the manifest, or without a valid
 * grant signed by the right key for this endpoint and kind, is refused by the
 * agent itself, whatever the hub sends.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#ifdef _WIN32
#include <winsock2.h>
#include <windows.h>
#include <direct.h>
#else
#include <unistd.h>
#include <sys/stat.h>
#endif

#include "../include/agent_trust.h"
#include "trust_fixtures.h"
#ifndef _WIN32
#include "../include/release_verify_posix.h"
#endif

static int failures = 0;

static void expect(const char* name, bool ok) {
    if (!ok) {
        printf("  [-] %s\n", name);
        failures++;
    } else {
        printf("  [+] %s\n", name);
    }
}

static char g_dir[200];

static void make_dir(void) {
#ifdef _WIN32
    char tmp[MAX_PATH];
    GetTempPathA(sizeof(tmp), tmp);
    snprintf(g_dir, sizeof(g_dir), "%sominull-trust-%lu", tmp, (unsigned long)GetCurrentProcessId());
    _mkdir(g_dir);
#else
    snprintf(g_dir, sizeof(g_dir), "/tmp/ominull-trust-XXXXXX");
    if (!mkdtemp(g_dir)) {
        perror("mkdtemp");
        exit(2);
    }
#endif
}

static void remove_dir(void) {
    const char* files[] = {"response.pub", "auto_isolate.pub", "policy.pub", "trust.pin", "trust.epoch", "manifest.state", "manifest.floor",
                           "capability.ceiling", "enforcement.state"};
    char path[400];
    for (size_t i = 0; i < sizeof(files) / sizeof(files[0]); i++) {
        snprintf(path, sizeof(path), "%s" TRUST_SEP "%s", g_dir, files[i]);
        remove(path);
    }
#ifdef _WIN32
    _rmdir(g_dir);
#else
    rmdir(g_dir);
#endif
}

static TrustContext T;
static char resp[65536];

#ifdef _WIN32
/* The Windows verifier is CNG with the compiled-in release key (updater.c);
 * here a table of the pairs the fixture release key signed stands in. */
static bool fake_verify(const char* msg, size_t len, const uint8_t* der, size_t derlen) {
    static const char* sigs[] = {FX_TB_SIG, FX_TB_SIG_OTHER_KEYS, FX_TB_SIG_OLD, FX_TB_SIG_TENANT, FX_TB_SIG_NEXT};
    const char* msgs[] = {FX_TB_STATEMENT, FX_TB_STATEMENT_OTHER_KEYS, FX_TB_STATEMENT_OLD, FX_TB_STATEMENT_TENANT, FX_TB_STATEMENT_NEXT};
    for (int i = 0; i < 5; i++) {
        uint8_t want[160];
        size_t wl = Response_Base64Decode(sigs[i], strlen(sigs[i]), want, sizeof(want));
        if (len == strlen(msgs[i]) && memcmp(msg, msgs[i], len) == 0 && derlen == wl && memcmp(der, want, wl) == 0) return true;
    }
    return false;
}
#endif

static void init(void) {
    Trust_Init(&T, FX_ENDPOINT, g_dir, g_dir, false);
#ifdef _WIN32
    T.verify_release = fake_verify;
#else
    g_ReleaseVerifyPem = FX_TB_PUB_PEM;
    snprintf(g_ReleaseVerifyDir, sizeof(g_ReleaseVerifyDir), "%s", g_dir);
    T.verify_release = ReleaseVerifyPosix;
#endif
}

/* A trust offer as the hub sends it: the keys plus the bundle signature. */
static char offer_buf[2][1024];
static const char* offer(int slot, const char* keys, const char* sig) {
    size_t n = strlen(keys);
    if (!sig) return keys;
    snprintf(offer_buf[slot], sizeof(offer_buf[slot]), "%.*s,\"bundle_sig\":\"%s\"}", (int)(n - 1), keys, sig);
    return offer_buf[slot];
}

/* A heartbeat answer as the hub writes it, with optional parts. */
static void beat(int64_t now, const char* keys, const char* manifest, const char* const* grants, int ngrants) {
    int off = snprintf(resp, sizeof(resp), "{\"status\":\"ok\",\"quarantined_peers\":[\"10.0.0.250\"],\"is_isolated\":true,"
                                           "\"isolation_allow_ips\":[\"10.0.0.251\"],\"isolation_baseline\":[]");
    if (keys) off += snprintf(resp + off, sizeof(resp) - off, ",\"trust\":%s", keys);
    if (manifest) off += snprintf(resp + off, sizeof(resp) - off, ",\"capability_manifest\":%s", manifest);
    if (ngrants) {
        off += snprintf(resp + off, sizeof(resp) - off, ",\"enforcement_grants\":[");
        for (int i = 0; i < ngrants; i++) off += snprintf(resp + off, sizeof(resp) - off, "%s%s", i ? "," : "", grants[i]);
        off += snprintf(resp + off, sizeof(resp) - off, "]");
    }
    /* Marks a hub might send are ignored: bootstrap marks come from the
     * agent's own clock. */
    off += snprintf(resp + off, sizeof(resp) - off, ",\"enforcement_marks\":{\"iso\":9999999999,\"mesh\":9999999999}}");
    Trust_ProcessHeartbeat(&T, resp, strlen(resp), now);
}

static void one(int64_t now, const char* grant) {
    const char* g[1] = {grant};
    beat(now, NULL, NULL, g, 1);
}

static bool refused_with(const char* needle) { return strstr(T.refused, needle) != NULL; }

static void test_versions(void) {
    printf("[*] version monotonicity\n");
    expect("1.8.56 > 1.8.55 admissible", Trust_UpdateVersionAdmissible("1.8.56", "1.8.55"));
    expect("1.10.0 > 1.9.9 admissible (numeric, not lexical)", Trust_UpdateVersionAdmissible("1.10.0", "1.9.9"));
    expect("same version refused", !Trust_UpdateVersionAdmissible("1.8.55", "1.8.55"));
    expect("downgrade refused", !Trust_UpdateVersionAdmissible("1.8.54", "1.8.55"));
    expect("1.8 == 1.8.0 refused", !Trust_UpdateVersionAdmissible("1.8", "1.8.0"));
    expect("malformed refused", !Trust_UpdateVersionAdmissible("1.8.x", "1.8.0"));
    expect("empty refused", !Trust_UpdateVersionAdmissible("", "1.8.0"));
    expect("huge part refused", !Trust_UpdateVersionAdmissible("1.9999999999", "1.0"));
    expect("leading text refused", !Trust_UpdateVersionAdmissible("v2.0.0", "1.0.0"));
    char st[512];
    Trust_ReleaseStatement("ominull-agent_9.9.9_amd64.deb", "9.9.9",
                           "abababababababababababababababababababababababababababababababab", st, sizeof(st));
    expect("release statement matches the Go form byte for byte", strcmp(st, FX_RELEASE_STATEMENT) == 0);
}

static void test_ip(void) {
    printf("[*] address literals\n");
    expect("v4 ok", Trust_IsIPLiteral("10.0.0.9"));
    expect("v4 out of range refused", !Trust_IsIPLiteral("10.0.0.256"));
    expect("v4 short refused", !Trust_IsIPLiteral("10.0.0"));
    expect("v6 ok", Trust_IsIPLiteral("fd00::1"));
    expect("v6 full ok", Trust_IsIPLiteral("1:2:3:4:5:6:7:8"));
    expect("v6 double :: refused", !Trust_IsIPLiteral("1::2::3"));
    expect("v6 long group refused", !Trust_IsIPLiteral("12345::1"));
    expect("cidr refused", !Trust_IsIPLiteral("0.0.0.0/0"));
    expect("name refused", !Trust_IsIPLiteral("example"));
    printf("[*] threat indicators only for public addresses\n");
    expect("public v4", Trust_PublicAddress("8.8.8.8") && Trust_PublicAddress("1.2.3.4"));
    const char* local[] = {"10.0.0.1", "127.0.0.53", "192.168.1.1", "172.16.0.1", "172.31.255.255", "169.254.1.1",
                           "100.64.0.1", "224.0.0.251", "255.255.255.255", "0.0.0.0", "::1", "::", "fe80::1",
                           "fd00::1", "ff02::1", "2001:db8::1", "::ffff:1:2", NULL};
    for (int i = 0; local[i]; i++) {
        char what[96];
        snprintf(what, sizeof(what), "%s is not dropped", local[i]);
        expect(what, !Trust_PublicAddress(local[i]));
    }
    expect("public v6", Trust_PublicAddress("2606:4700::1111") && Trust_PublicAddress("2a00:1450:4001::1"));
    expect("172.32 is public", Trust_PublicAddress("172.32.0.1"));
}

static void test_pinning_and_bootstrap(int64_t now) {
    printf("[*] key pinning and one-time bootstrap\n");
    init();
    expect("fresh host has no keys", !T.have_key[0] && !T.have_key[1] && !T.have_key[2]);
    expect("fresh host has no state file", !T.state.exists);
    int64_t boot = FX_T0 - 4 * 86400;   /* the upgrade happened before every fixture grant */
    beat(boot, FX_KEYS_JSON, NULL, NULL, 0);
    expect("an unsigned trust offer pins nothing", !T.have_key[0] && !T.have_key[1] && !T.have_key[2] && refused_with("not signed"));
    expect("bootstrap marks come from this host's clock, not the hub", T.state.iso_seen == boot - 60 && T.state.mesh_seen == boot - 60);
    beat(boot, offer(0, FX_KEYS_JSON, FX_TB_SIG_WRONG_SIGNER), NULL, NULL, 0);
    expect("a bundle signed by another key pins nothing", !T.have_key[0] && refused_with("does not verify"));
    beat(boot, offer(0, FX_KEYS_OTHER_KEYS_JSON, FX_TB_SIG), NULL, NULL, 0);
    expect("a genuine signature over other keys pins nothing", !T.have_key[0]);
    beat(boot, offer(0, FX_KEYS_TENANT_JSON, FX_TB_SIG_TENANT), NULL, NULL, 0);
    expect("another tenant's genuine bundle pins nothing", !T.have_key[0] && refused_with("another tenant"));
    beat(boot, offer(0, FX_KEYS_JSON, FX_TB_SIG), NULL, NULL, 0);
    expect("three keys pinned from the release-signed bundle", T.have_key[0] && T.have_key[1] && T.have_key[2]);
    expect("tenant and epoch pinned with them", strcmp(T.tenant, "default") == 0 && T.epoch == 2 && T.epoch_floor == 2);
    expect("bootstrap adopted the hub's isolation once", T.state.isolated && strcmp(T.state.source, "bootstrap") == 0);
    expect("bootstrap adopted allow list", T.state.allowCount == 1 && strcmp(T.state.allow[0], "10.0.0.251") == 0);
    expect("bootstrap adopted mesh peers", T.state.meshCount == 1 && T.state.mesh[0].on);
    expect("bootstrap isolation releases on dead-man as before", Trust_DeadmanBeats(&T, 100, 3000) == 100);

    beat(now, offer(1, FX_KEYS_OTHER_KEYS_JSON, FX_TB_SIG_OTHER_KEYS), NULL, NULL, 0);
    expect("a different, release-signed key set does not replace the pins", T.mismatch[0] && T.mismatch[1] && T.mismatch[2]);
    char report[768];
    Trust_ReportJSON(&T, report, sizeof(report));
    expect("report says mismatch", strstr(report, "\"keys\":\"mismatch\"") != NULL);
    init();
    uint8_t want[32];
    Trust_HexKey(FX_RESPONSE_PUB, want);
    expect("pinned response key survives the offer", T.have_key[0] && memcmp(T.keys[0], want, 32) == 0);
    expect("state persisted across restart", T.state.exists && T.state.isolated);
}

static void test_manifest(int64_t now) {
    printf("[*] capability manifest\n");
    init();
    expect("no manifest: only updates allowed", Trust_Allows(&T, "agent_update") && !Trust_Allows(&T, "terminal_session") &&
                                                 !Trust_Allows(&T, "isolation_change"));
    beat(now, NULL, FX_M_FORGED_3, NULL, 0);
    expect("manifest signed by another key refused", !T.manifest.have && refused_with("does not verify"));
    beat(now, NULL, FX_M_OTHER_EP_3, NULL, 0);
    expect("manifest for another endpoint refused", !T.manifest.have);
    beat(now, NULL, FX_M_RESPOND_1, NULL, 0);
    expect("respond manifest accepted", T.manifest.have && T.manifest.seq == 1 && strcmp(T.manifest.profile, "respond") == 0);
    expect("respond allows terminal, collect, isolate, mesh", Trust_Allows(&T, "terminal_session") && Trust_Allows(&T, "forensic_collection") &&
                                                          Trust_Allows(&T, "isolation_change") && Trust_Allows(&T, "mesh_quarantine"));
    expect("respond does not allow scripts", !Trust_Allows(&T, "script_exec"));
    beat(now, NULL, FX_M_ENGAGEMENT_1, NULL, 0);
    expect("same-seq different manifest refused (no replay of a sibling)", strcmp(T.manifest.profile, "respond") == 0);
    init();
    expect("manifest persisted across restart", T.manifest.have && T.manifest.seq == 1);

    printf("[*] local capability ceiling\n");
    expect("ceiling set to monitor", Trust_SetCeiling(&T, "monitor"));
    init();
    expect("a monitor ceiling caps a respond manifest", !Trust_Allows(&T, "isolation_change") && !Trust_Allows(&T, "terminal_session") &&
                                                       !Trust_Allows(&T, "mesh_quarantine") && Trust_Allows(&T, "agent_update"));
    char report[768];
    Trust_ReportJSON(&T, report, sizeof(report));
    expect("report carries the ceiling", strstr(report, "\"ceiling\":\"monitor\"") != NULL);
    expect("unknown ceiling refused", !Trust_SetCeiling(&T, "everything"));
    expect("ceiling removed", Trust_SetCeiling(&T, "none"));
    init();
    expect("without a ceiling the manifest decides", Trust_Allows(&T, "terminal_session"));
}

static void test_grants(int64_t now) {
    printf("[*] enforcement grants\n");
    init();
    /* Start from a released host so each step is visible. */
    Trust_LocalRelease(&T);
    expect("local release clears isolation", !T.state.isolated && strcmp(T.state.source, "local") == 0);

    one(now, FX_G_ISO_EXPIRED);
    expect("expired grant refused", !T.state.isolated && refused_with("expired"));
    one(now, FX_G_ISO_FORGED);
    expect("forged isolation refused", !T.state.isolated && refused_with("does not verify"));
    expect("forged far-future grant does not move the watermark", T.state.iso_seen < FX_T0);
    one(now, FX_G_ISO_OTHER_EP);
    expect("grant for another endpoint refused", !T.state.isolated && refused_with("another endpoint"));
    one(now, FX_G_ISO_TAMPERED);
    expect("payload changed after signing refused", !T.state.isolated && refused_with("digest"));
    one(now, FX_G_ISO_DUP_ROUTE);
    expect("duplicate route keys refused", !T.state.isolated);
    one(now, FX_G_ISO_CASE_ROUTE);
    expect("case-variant keys refused", !T.state.isolated);
    one(now, FX_G_ISO_ESC_ROUTE);
    expect("escaped key refused", !T.state.isolated);
    one(now, FX_G_MESH_KIND_ISO);
    expect("mesh-kind grant over an isolation route refused", !T.state.isolated && T.state.meshCount <= 1);
    one(now, FX_G_AUTO_SIGNED_OWNER);
    expect("auto kind signed by the owner key refused", !T.state.isolated);
    one(now, FX_G_OWNER_SIGNED_AUTO);
    expect("owner kind signed by the auto key refused", !T.state.isolated);

    one(now, FX_G_ISO_OTHER_EP_LATE);
    expect("a newer genuine grant for another endpoint does not move this host's mark", T.state.iso_seen < FX_T0 + 10 &&
                                                                                        refused_with("another endpoint"));
    one(now, FX_G_ISO);
    expect("owner isolation applied", T.state.isolated && strcmp(T.state.source, "owner") == 0);
    expect("owner allow list applied", T.state.allowCount == 1 && strcmp(T.state.allow[0], "10.0.0.9") == 0);
    expect("owner isolation holds 12 h on the dead-man (3 s beats)", Trust_DeadmanBeats(&T, 100, 3000) == 14400);
    expect("owner isolation holds 12 h on the dead-man (2.5 s beats)", Trust_DeadmanBeats(&T, 120, 2500) == 17280);

    one(now, FX_G_AUTO_RELEASE);
    expect("auto-isolation key cannot release", T.state.isolated && refused_with("other than isolating"));
    one(now, FX_G_REL);
    expect("owner release applied", !T.state.isolated && strcmp(T.state.source, "none") == 0);
    one(now, FX_G_ISO);
    expect("replayed older isolation ignored", !T.state.isolated);
    one(now, FX_G_AUTO);
    expect("detector isolation applied", T.state.isolated && strcmp(T.state.source, "auto") == 0 && T.state.allowCount == 0);
    expect("detector isolation keeps the 5 min dead-man", Trust_DeadmanBeats(&T, 100, 3000) == 100);

    one(now, FX_G_MESH_ON);
    bool on = false;
    for (int i = 0; i < T.state.meshCount; i++) if (strcmp(T.state.mesh[i].ip, "10.0.0.66") == 0 && T.state.mesh[i].on) on = true;
    expect("mesh quarantine applied", on);
    one(now, FX_G_MESH_OFF);
    on = false;
    for (int i = 0; i < T.state.meshCount; i++) if (strcmp(T.state.mesh[i].ip, "10.0.0.66") == 0 && T.state.mesh[i].on) on = true;
    expect("mesh quarantine lifted", !on);
    one(now, FX_G_MESH_ON);
    on = false;
    for (int i = 0; i < T.state.meshCount; i++) if (strcmp(T.state.mesh[i].ip, "10.0.0.66") == 0 && T.state.mesh[i].on) on = true;
    expect("replayed quarantine ignored", !on);

    one(now, FX_G_REL_AUTO);
    expect("owner releases the detector's isolation", !T.state.isolated);

    beat(now, NULL, FX_M_MONITOR_2, NULL, 0);
    expect("narrower manifest accepted", strcmp(T.manifest.profile, "monitor") == 0);
    one(now, FX_G_BULK_ISO);
    expect("isolation refused outside the manifest", !T.state.isolated && refused_with("manifest"));
    beat(now, NULL, FX_M_RESPOND_1, NULL, 0);
    expect("older manifest refused", strcmp(T.manifest.profile, "monitor") == 0 && refused_with("older"));
    beat(now, NULL, FX_M_RESPOND_3, NULL, 0);
    one(now, FX_G_ISO_3);
    expect("isolation accepted again under a newer respond manifest", T.state.isolated);
    beat(now, NULL, FX_M_RESPOND_3, NULL, 0);
    one(now, FX_G_FUTURE_FORGED);
    expect("forged release refused", T.state.isolated);

    init();
    expect("authorized state survives a restart", T.state.isolated && strcmp(T.state.source, "owner") == 0);

    one(now, FX_G_ISO_RULES);
    expect("an isolation's bound exceptions are applied with it", T.state.isolated && T.state.ruleCount == 2 &&
                                                                     strcmp(T.state.rules[0].destination, "192.0.2.53") == 0 &&
                                                                     T.state.rules[1].port == 67);
    init();
    expect("bound exceptions survive a restart", T.state.ruleCount == 2 && strcmp(T.state.rules[0].service, "dns") == 0);
    one(now, FX_G_ISO_RULES_BAD);
    expect("an exception that is not an address refuses the isolation", T.state.ruleCount == 2 && refused_with("exceptions"));
    one(now, FX_G_ISO_RULES_TWICE);
    expect("a host named in two exception sets is refused", T.state.ruleCount == 2 && refused_with("twice"));
    one(now, FX_G_REL_RULES);
    expect("release clears the exceptions", !T.state.isolated && T.state.ruleCount == 0);
}

static void test_monitor_release(int64_t now) {
    printf("[*] narrowing never frees a contained host\n");
    make_dir();
    init();
    beat(FX_T0 - 4 * 86400, offer(0, FX_KEYS_JSON, FX_TB_SIG), FX_M_RESPOND_1, NULL, 0);
    Trust_LocalRelease(&T);
    one(now, FX_G_ISO);
    expect("isolated under respond", Trust_EffectiveIsolated(&T));
    beat(now, NULL, FX_M_MONITOR_2, NULL, 0);
    expect("still isolated after the manifest narrows", Trust_EffectiveIsolated(&T));
    one(now, FX_G_REL);
    expect("release accepted under a monitor manifest", !Trust_EffectiveIsolated(&T));
    remove_dir();
}

static void test_offers_and_updates(int64_t now) {
    printf("[*] response offers and agent updates\n");
    make_dir();
    init();
    beat(FX_T0 - 4 * 86400, offer(0, FX_KEYS_JSON, FX_TB_SIG), FX_M_RESPOND_1, NULL, 0);
    ResponseGrant g;
    memset(&g, 0, sizeof(g));
    snprintf(g.action_kind, sizeof(g.action_kind), "isolation_change");
    expect("offer kind must equal the grant's kind", Trust_OfferRefusal(&T, "terminal_session", &g) != NULL);
    snprintf(g.action_kind, sizeof(g.action_kind), "terminal_session");
    snprintf(g.tenant_id, sizeof(g.tenant_id), "other");
    expect("an offer for another tenant is refused", Trust_OfferRefusal(&T, "terminal_session", &g) != NULL);
    snprintf(g.tenant_id, sizeof(g.tenant_id), "default");
    expect("terminal allowed under respond", Trust_OfferRefusal(&T, "terminal_session", &g) == NULL);
    snprintf(g.action_kind, sizeof(g.action_kind), "script_exec");
    expect("script refused under respond", Trust_OfferRefusal(&T, "script_exec", &g) != NULL);
    snprintf(g.action_kind, sizeof(g.action_kind), "agent_update");
    expect("update grant is not a response job", Trust_OfferRefusal(&T, "agent_update", &g) != NULL);

    char r[16384];
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"},\"agent_update_grant\":%s}", FX_G_UPDATE);
    expect("owner-approved update accepted", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now) == NULL);
    expect("update grant for another version refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.8", now) != NULL);
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"}}");
    expect("update without a grant refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now) != NULL);
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"},\"agent_update_grant\":%s}", FX_G_UPDATE_FORGED);
    expect("forged update grant refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now) != NULL);
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"},\"agent_update_grant\":%s}", FX_G_UPDATE_OTHER_EP);
    expect("update grant for another endpoint refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now) != NULL);
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"},\"agent_update_grant\":%s}", FX_G_UPDATE_AS_ISO);
    expect("update payload under an isolation grant refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now) != NULL);
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"},\"agent_update_grant\":%s}", FX_G_UPDATE);
    expect("update grant expired after 7 days refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now + 8 * 86400) != NULL);
    one(now, FX_G_TERMINAL_AS_ISO);
    expect("terminal payload under an isolation grant refused", refused_with("route"));

    char report[768];
    Trust_ReportJSON(&T, report, sizeof(report));
    expect("report: keys pinned, manifest 1, respond", strstr(report, "\"keys\":\"pinned\"") && strstr(report, "\"manifest_seq\":1") &&
                                                          strstr(report, "\"profile\":\"respond\""));
    expect("report carries no key material", strstr(report, FX_RESPONSE_PUB) == NULL);

    char pinpath[400], savedpin[600] = "";
    snprintf(pinpath, sizeof(pinpath), "%s" TRUST_SEP "trust.pin", g_dir);
    Trust_ReadSmallFile(&T, pinpath, savedpin, sizeof(savedpin));
    expect("explicit re-pin removes the pinned bundle", Trust_Repin(&T) == 1);
    /* Interrupted after the floor was written, before the pin went: the
     * retry finishes without climbing past the next epoch. */
    Trust_WriteFile(&T, pinpath, savedpin, false);
    init();
    expect("a retried re-pin removes the pin again", Trust_Repin(&T) == 1);
    init();
    expect("after re-pin no key is trusted", !T.have_key[0] && !T.have_key[1] && !T.have_key[2]);
    expect("the re-pin raises the epoch floor past the revoked bundle", T.epoch_floor == 3);
    expect("a second re-pin with nothing pinned does not climb", Trust_Repin(&T) == 0);
    init();
    expect("the floor stays one above the revoked bundle", T.epoch_floor == 3);
    beat(FX_T0, offer(0, FX_KEYS_OLD_JSON, FX_TB_SIG_OLD), NULL, NULL, 0);
    expect("an older, genuinely signed bundle is not pinned again", !T.have_key[0] && refused_with("older"));
    beat(FX_T0, offer(0, FX_KEYS_JSON, FX_TB_SIG), NULL, NULL, 0);
    expect("the revoked bundle (same epoch) is not pinned again after a re-pin", !T.have_key[0] && refused_with("older"));
    beat(FX_T0, offer(0, FX_KEYS_NEXT_JSON, FX_TB_SIG_NEXT), NULL, NULL, 0);
    expect("the next epoch's bundle pins", T.have_key[0] && T.epoch == 3);
    beat(FX_T0, NULL, FX_M_ENGAGEMENT_1, NULL, 0);
    expect("after a re-pin an older, wider manifest is not taken", !(T.manifest.have && strcmp(T.manifest.profile, "engagement") == 0) &&
                                                                 refused_with("older"));
    {
        /* The floor follows the policy key, not the bundle epoch: with the
         * manifest file gone and the epoch moved (another key or a raised
         * authority floor), an older manifest under the same key is refused. */
        int64_t seq = T.manifest.seq;
        char path[400], saved[1024];
        Trust_ManifestJSON(&T.manifest, saved, sizeof(saved));
        snprintf(path, sizeof(path), "%s" TRUST_SEP "manifest.state", g_dir);
        remove(path);
        init();
        expect("the floor survives without the manifest file", T.mfloorCount == 1 && T.mfloor[0].seq == seq && !T.manifest.have);
        T.epoch = 99;
        beat(FX_T0, NULL, FX_M_ENGAGEMENT_1, NULL, 0);
        expect("an older manifest under the same policy key is refused at another epoch",
               !T.manifest.have && refused_with("already taken under this policy key"));
        /* A floor behind the stored manifest (stop between the two writes) is
         * raised from the manifest at start. */
        Trust_WriteFile(&T, path, saved, false);
        snprintf(path, sizeof(path), "%s" TRUST_SEP "manifest.floor", g_dir);
        remove(path);
        init();
        expect("the floor is raised from the stored manifest", T.manifest.have && T.mfloorCount == 1 && T.mfloor[0].seq == T.manifest.seq);
        beat(FX_T0, NULL, NULL, NULL, 0);
        expect("the raised floor is made durable on the next beat", !T.mfloor_dirty && Trust_PathExists(path));
        /* Recovered at start, then a re-pin straight away (no beat): the
         * floor is written before the pin goes. */
        remove(path);
        init();
        expect("floor recovered in memory only", T.mfloor_dirty && !Trust_PathExists(path));
        char pinpath2[400], keep[600] = "", ep[400], keepep[64] = "";
        snprintf(pinpath2, sizeof(pinpath2), "%s" TRUST_SEP "trust.pin", g_dir);
        snprintf(ep, sizeof(ep), "%s" TRUST_SEP "trust.epoch", g_dir);
        Trust_ReadSmallFile(&T, pinpath2, keep, sizeof(keep));
        Trust_ReadSmallFile(&T, ep, keepep, sizeof(keepep));
        expect("a re-pin with a recovered floor succeeds", Trust_Repin(&T) == 1);
        init();
        expect("and the floor is on disk after it", Trust_PathExists(path) && T.mfloorCount == 1 && T.mfloor[0].seq == seq);
        Trust_WriteFile(&T, pinpath2, keep, false);   /* put the pin back for the checks below */
        Trust_WriteFile(&T, ep, keepep, false);
        init();
        /* A policy key that comes back (A, B, A) keeps its own floor. */
        uint8_t a[32];
        memcpy(a, T.keys[TRUST_KEY_POLICY], 32);
        expect("policy key A floor written", Trust_RaiseManifestFloor(&T, seq));
        memset(T.keys[TRUST_KEY_POLICY], 0x42, 32);
        expect("policy key B floor written", Trust_RaiseManifestFloor(&T, 1));
        init();
        expect("both policy keys keep a floor", T.mfloorCount == 2);
        memcpy(T.keys[TRUST_KEY_POLICY], a, 32);
        expect("key A's floor is still in force after B", Trust_ManifestFloored(&T, seq) && !Trust_ManifestFloored(&T, seq + 1));
    }
    remove_dir();
}

int main(void) {
    int64_t now = FX_T0 + 100;
    test_versions();
    test_ip();
    make_dir();
    test_pinning_and_bootstrap(now);
    test_manifest(now);
    test_grants(now);
    remove_dir();
    test_monitor_release(now);
    test_offers_and_updates(now);
    if (failures) {
        printf("[-] agent trust: %d failure(s)\n", failures);
        return 1;
    }
    printf("[+] agent trust: all checks passed\n");
    return 0;
}
